  const b = [...(r.batches ?? [])].sort((x, y) => x.id - y.id), final = b.find(x => x.id === r.batch) ?? b.at(-1);
  return (final?.probes.at(-1)?.checks ?? []).filter((/** @type {any} */ c) => c.verdict === 'red' && !c.reason && Number.isSafeInteger(c.job)).map((/** @type {any} */ c) => c.job);
