  const batches = [...(r.batches ?? [])].sort((a, b) => a.id - b.id);
  const final = batches.find(b => b.id === r.batch) ?? batches.at(-1) ?? null;
  const earlier = batches.filter(b => b !== final && t(b.formedAt) != null);
