const median = (/** @type {number[]} */ xs) => {
  if (!xs.length) return null;
  const s = [...xs].sort((a, b) => a - b), m = s.length >> 1;
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

/** Merged changes over `days` before `now` by signature: their median time when quiet and when busy, and how many of each. @param {any[]} all analyses */
export function typical(all, now, days = 30) {
  /** @type {Record<string, {quiet: number[], busy: number[]}>} */ const by = {};
  for (const a of all) {
    if (a.outcome !== 'merged' || a.seconds == null || a.signature === 'none' || now - t(a.endedAt) > days * 86400000) continue;
    (by[a.signature] ??= {quiet: [], busy: []})[a.busy ? 'busy' : 'quiet'].push(a.seconds);
  }
  return Object.fromEntries(Object.entries(by).map(([k, v]) => [k, {quiet: {n: v.quiet.length, median: median(v.quiet)}, busy: {n: v.busy.length, median: median(v.busy)}, days}]));
}

/**
 * The agent usage of a change's branch (agent-usage.mjs `branchTotals`), or null: matched by repo name and head branch, and only when
 * the branch was first used no later than the change ended, so a reused branch name does not borrow a later PR's work.
 * @param {any} a an analysis @param {Record<string, any>} branches
 */
export function agentsFor(a, branches) {
  const u = a.branch ? branches[`${String(a.repo).split('/').pop()}\n${a.branch}`] : null;
  if (!u || (a.endedAt && u.first > String(a.endedAt).slice(0, 10))) return null;
  return {out: u.out, in: u.in, cacheRead: u.cacheRead, responses: u.responses, byAgent: u.byAgent, first: u.first, last: u.last,
    start: u.start ?? null, end: u.end ?? null};
}

/** Each PR's newest visual review in Hangar (`GET /v1/reviews?kind=pr`: newest revision first), at a glance for the list, by
 * `owner/repo/pr` lowercased: views, changes, the producer's status and the first after image (the thumbnail). @param {any[]} reviews */
export function reviewGlance(reviews) {
  /** @type {Map<string, {views: number, changes: number, status: string, cover: string | null}>} */ const by = new Map();
  for (const r of reviews) {
    const key = `${String(r.repo).toLowerCase()}/${r.number}`;
    if (r.kind !== 'pr' || by.has(key)) continue;
    by.set(key, {views: r.entries.reduce((/** @type {number} */ n, /** @type {any} */ e) => n + e.pairs.length, 0), changes: r.entries.length,
      status: r.status ?? '', cover: r.entries[0]?.pairs[0]?.after ?? null});
  }
  return by;
}

/** The index row, with its review at a glance (`reviewGlance`) or null. @param {any} a @param {any} [review] */
export const changeRow = (a, review = null) => ({repo: a.repo, pr: a.pr, title: a.title, outcome: a.outcome, reason: a.reason ?? null, queuedAt: a.queuedAt, endedAt: a.endedAt, seconds: a.seconds,
  signature: a.signature, busy: a.busy, setBy: a.setBy ? `${a.setBy.check} on ${a.setBy.worker}` : null,
  wait: Object.entries(a.waits).filter(([c]) => BUSY.has(c)).reduce((n, [, v]) => n + v, 0), batch: a.batch,
  agents: a.agents ? {out: a.agents.out, byAgent: a.agents.byAgent} : null,
  // the machines' time on its checks (each job that ran, not one answered from the cache), and from the agents' first response
  // on its branch to the merge
  ci: Object.values(a.jobs ?? {}).filter((/** @type {any} */ j) => !j.missing && !j.cachedFrom && j.started && j.finished)
    .reduce((n, /** @type {any} */ j) => n + (Date.parse(j.finished) - Date.parse(j.started)) / 1000, 0),
  wall: a.agents?.start && a.endedAt ? Math.max(0, (Date.parse(a.endedAt) - Date.parse(a.agents.start)) / 1000) : null, review});
